import{_ as o,l as s,o as n,b as l,q as p,d as e,f as r,m as d}from"./chunks/framework.Tf23FRXt.js";const T=JSON.parse('{"title":"万魔殿 边境之狱4","description":"","frontmatter":{},"headers":[],"relativePath":"duty/800.htm.md","filePath":"duty/800.md","lastUpdated":1791101830000}'),i={name:"duty/800.htm.md"};function m(u,t,_,S,f,k){const a=s("Status");return n(),l("div",null,[t[4]||(t[4]=p('<h1 id="万魔殿-边境之狱4" tabindex="-1">万魔殿 边境之狱 4</h1><p>场地边缘为即死区，要注意。</p><p>BOSS 读条<mark>布置剧场</mark>后，场地会落下幕布，幕布掀开后，会出现不同的场地。幕布中央的圆坑不能踩，踩了会中很疼很疼的 DOT（走出来就消失）。</p><p>幕布会随着之后<mark>板画</mark>的读条造成不同的效果：</p><ul><li>雷板画：雷地板生成 AOE，同时场地中央距离衰减 AOE，需要在雷地板以外的场地贴边躲避。</li><li>水板画：水地板生成 AOE，同时从场地中央击退，可以开防击退处理，否则需要站在场地中央躲开水地板方向击退。</li><li>毒地板：单人点名 AOE，需要躲开毒地板的同时散开处理。</li><li>火地板：分摊，注意躲开火地板，集合分摊即可。</li></ul><p>出现塔的时候，职能图标上标有禁止的叉子，表示该职能的人不能踩塔。请在保证所有塔都有人的前提下，正确踩塔。</p><p>BOSS 回到场中读条<mark>换位强袭东 / 西 / 南 / 北</mark>时，场地对应一侧会出现<strong>剑</strong>或是<strong>斗篷</strong>的标记，如果是剑，需要在标记两侧躲避，如果是斗篷，需要在标记正面（击退）处理。</p>',7)),e("p",null,[t[0]||(t[0]=r("BOSS 读条",-1)),t[1]||(t[1]=e("mark",null,"聚血",-1)),t[2]||(t[2]=r("后，场地四周出现 8 个球，并与玩家连线。球上会出现禁止的职能叉子，请在保证撞对的前提下处理，一个人最多可以撞 2 个球（撞 3 个会获得",-1)),d(a,{id:2519,name:"死亡宣告"}),t[3]||(t[3]=r("debuff）。",-1))]),t[5]||(t[5]=e("p",null,"后续均为机制复读或组合机制。",-1))])}const A=o(i,[["render",m]]);export{T as __pageData,A as default};
